const item = $input.item.json;

// ==============================
// DATOS DEL TELEGRAM TRIGGER
// ==============================
const chatId = item.message.chat.id;
const telegramUser = String(item.message.from.id);
const nombreUsuario = item.nombre || item.message.from.first_name || "";

const textoRaw = (item.message.text || "")
  .trim()
  .replace(/[‐-―−]/g, "-")
  .replace(/[ ​-‍﻿]/g, "");

// ==============================
// DATOS DEL USUARIO
// ==============================
const permitido = item.permitido ?? true;
const rolUsuario = item.rol || "usuario";

// ==============================
// SESIÓN
// ==============================
const session = {
  pantalla_actual: item.pantalla_actual || "MENU_PRINCIPAL",
  paso_actual: item.paso_actual || "",
  datos_parciales: item.datos_parciales || "{}",
};

// ==============================
// VARIABLES DE TRABAJO
// ==============================
let pantalla = session.pantalla_actual;
let paso = session.paso_actual;

let datos = {};

try {
  datos = session.datos_parciales
    ? JSON.parse(session.datos_parciales)
    : {};
} catch (e) {
  datos = {};
}

// ── Control de acceso ───────────────────────────
if (permitido === false) {
  return [{
    json: {
      chatId,
      telegramUser,
      respuesta: `🚫 Acceso restringido.

Tu usuario no está autorizado para usar AgendaBot.

Contacta al administrador para solicitar acceso.`,
      nuevaPantalla: "MENU_PRINCIPAL",
      nuevoPaso: "",
      nuevosDatos: "{}",
      accion: "NINGUNA",
      pantallaLog: "ACCESO_DENEGADO",
      opcionLog: textoRaw,
    },
  }];
}

// ── Control de acceso (Artículo 12) ───────────────────────────────────────────
if (permitido === false) {
  return [{ json: {
    chatId, telegramUser,
    respuesta: `🚫 Acceso restringido.\n\nTu usuario no está autorizado para usar AgendaBot.\nContacta al administrador para solicitar acceso.`,
    nuevaPantalla: "MENU_PRINCIPAL", nuevoPaso: "", nuevosDatos: "{}",
    accion: "NINGUNA", pantallaLog: "ACCESO_DENEGADO", opcionLog: textoRaw
  }}];
}

// ── Textos base ──────────────────────────────────────────────────────────────
const MENU_PRINCIPAL_TXT = `🧭 ¿En qué te puedo ayudar hoy?\n\n**Menú principal:**\n- **0.** Ayuda\n- **1.** Agenda (citas)\n- **2.** Tareas\n- **3.** Recordatorios\n- **4.** Hábitos\n- **5.** Listas\n- **6.** Reportes\n- **7.** Configuración\n- **8.** Administrador\n\nSi quieres empezar rápido, te recomiendo la opción **1 (Agenda)**.`;

const BIENVENIDA = `Hola, soy **AgendaBot** 👋\n\nEstoy aquí para ayudarte a organizar tus citas, tareas y recordatorios de forma sencilla y sin complicaciones.\n\nPuedes escribirme en cualquier momento.\nPara avanzar, solo tienes que escribir el número de la opción que quieras usar.\n\n${MENU_PRINCIPAL_TXT}\n\n💡 Tip rápido: escribe solo el número (por ejemplo: **1**) y presiona enviar.`;

const MENU_AGENDA_TXT = `📅 Perfecto, vamos con tu **agenda**.\n\n¿Qué deseas hacer?\n\n- **1.** Agendar una nueva cita\n- **2.** Consultar tu agenda\n- **3.** Reprogramar una cita\n- **4.** Cancelar una cita\n- **5.** Marcar una cita como completada\n- **9.** Volver al menú principal (9)`;

const MENU_TAREAS_TXT = `📋 Vamos con tus **tareas**.\n\n¿Qué deseas hacer?\n\n- **1.** Crear tarea nueva\n- **2.** Ver tareas pendientes\n- **3.** Cambiar estado de tarea\n- **9.** Volver al menú principal (9)`;

const MENU_HABITOS_TXT = `🔁 Vamos con tus **hábitos**.\n\n¿Qué deseas hacer?\n\n- **1.** Crear nuevo hábito\n- **2.** Ver mis hábitos\n- **3.** Activar/Desactivar hábito\n- **9.** Volver al menú principal (9)`;

const MENU_RECORDATORIOS_TXT = `🔔 Vamos con tus **recordatorios**.\n\n¿Qué deseas hacer?\n\n- **1.** Crear recordatorio\n- **2.** Ver mis recordatorios\n- **9.** Volver al menú principal (9)`;

const MENU_LISTAS_TXT = `📃 Vamos con tus **listas**.\n\n¿Qué deseas hacer?\n\n- **1.** Crear una lista nueva\n- **2.** Ver mis listas\n- **3.** Agregar ítem a una lista\n- **4.** Ver ítems de una lista\n- **5.** Marcar ítem como completado\n- **9.** Volver al menú principal (9)`;

const MENU_ADMIN_TXT = `🛠️ **Panel de administrador**.\n\n- **1.** Ver usuarios\n- **2.** Ver logs recientes\n- **3.** Agregar nuevo usuario\n- **4.** Cambiar permiso de usuario\n- **9.** Volver al menú principal (9)`;

const MENU_REPORTES_TXT = `📊 Vamos con tus **reportes**.\n\n¿Qué quieres consultar?\n\n- **1.** Citas de hoy\n- **2.** Citas de esta semana\n- **9.** Volver al menú principal (9)`;

const MENU_CONFIGURACION_TXT = `⚙️ **Configuración**\n\n¿Qué deseas cambiar?\n\n- **1.** Cambiar mi nombre\n- **2.** Cambiar horario de recordatorios\n- **9.** Volver al menú principal (9)`;

const OPCION_INVALIDA = (opciones, pantallaNombre) =>
  `⚠️ Ups, esa opción no existe en este menú.\n\nPor favor escribe uno de los números que ves en pantalla.\n\nEstás en: **${pantallaNombre}**\nOpciones disponibles: **${opciones}**`;

// ── Helper central ───────────────────────────────────────────────────────────
function R(resp, nuevaPantalla, nuevoPaso, nuevosDatos, accion, opcionLog) {
  return { json: {
    chatId, telegramUser,
    respuesta: resp,
    nuevaPantalla,
    nuevoPaso: nuevoPaso || "",
    nuevosDatos: JSON.stringify(nuevosDatos || {}),
    accion: accion || "RESPONDER",
    pantallaLog: pantalla,
    opcionLog: opcionLog || textoRaw
  }};
}

// ── Validadores ──────────────────────────────────────────────────────────────
function esFechaValida(s) {
  if (!/^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/.test(s)) return false;
  const [y,m,d] = s.split('-').map(Number);
  return new Date(y,m-1,d) >= new Date(new Date().setHours(0,0,0,0));
}
function esHoraValida(s) { return /^([01]\d|2[0-3]):([0-5]\d)$/.test(s); }

// ── Primer uso / /start ──────────────────────────────────────────────────────
if (!session)                              return [R(BIENVENIDA, "MENU_PRINCIPAL","",{})];
if (textoRaw.toLowerCase()==="/start")     return [R(MENU_PRINCIPAL_TXT,"MENU_PRINCIPAL","",{})];

// ═══════════════════════════════════════════════════════════════════════════════
switch (pantalla) {

// ── MENÚ PRINCIPAL ────────────────────────────────────────────────────────────
case "MENU_PRINCIPAL": {
  if (!/^[0-8]$/.test(textoRaw))
    return [R(OPCION_INVALIDA("0 al 8","Menú principal")+"\n\n"+MENU_PRINCIPAL_TXT,"MENU_PRINCIPAL","",{})];
  switch(textoRaw){
    case "0": return [R(`ℹ️ **Ayuda:**\n- Escribe el número de la opción deseada.\n- Usa **9** para volver o cancelar en cualquier momento.\n\n${MENU_PRINCIPAL_TXT}`,"MENU_PRINCIPAL","",{})];
    case "1": return [R(MENU_AGENDA_TXT,"MENU_AGENDA","",{})];
    case "2": return [R(MENU_TAREAS_TXT,"MENU_TAREAS","",{})];
    case "3": return [R(MENU_RECORDATORIOS_TXT,"MENU_RECORDATORIOS","",{})];
    case "4": return [R(MENU_HABITOS_TXT,"MENU_HABITOS","",{})];
    case "5": return [R(MENU_LISTAS_TXT,"MENU_LISTAS","",{})];
    case "6": return [R(MENU_REPORTES_TXT,"MENU_REPORTES","",{})];
    case "7": return [R(MENU_CONFIGURACION_TXT,"MENU_CONFIGURACION","",{})];
    case "8":
      if (rolUsuario.startsWith("admin")===false) return [R(`⛔ No tienes permisos de administrador.\n\n${MENU_PRINCIPAL_TXT}`,"MENU_PRINCIPAL","",{})];
      return [R(MENU_ADMIN_TXT,"MENU_ADMIN","",{})];
  }
  break;
}

// ═══════════════════════════════════════════════════════════════════════════════
// OPCIÓN 1 — AGENDA COMPLETA
// ═══════════════════════════════════════════════════════════════════════════════
case "MENU_AGENDA": {
  if (textoRaw==="9") return [R(MENU_PRINCIPAL_TXT,"MENU_PRINCIPAL","",{})];
  if (!/^[1-5]$/.test(textoRaw))
    return [R(OPCION_INVALIDA("1,2,3,4,5,9","Menú Agenda")+"\n\n"+MENU_AGENDA_TXT,"MENU_AGENDA","",{})];
  if (textoRaw==="1") return [R(`Empecemos a crear tu cita.\n\nPaso 1 de 6\n¿Cuál es la fecha de la cita?\n\nFormato: YYYY-MM-DD\nEjemplo: 2025-12-20\n\n- **9.** Cancelar (9)`,"CITA_WIZARD","PASO1_FECHA",{})];
  if (textoRaw==="2") return [R(`📅 Consultar agenda\n\nEscribe la fecha que deseas consultar:\n\nFormato: YYYY-MM-DD\nEjemplo: 2025-12-20\n\n- **9.** Cancelar (9)`,"AGENDA_CONSULTAR","PASO1_FECHA",{})];
  if (textoRaw==="3") return [R(`🔄 Reprogramar cita\n\nEscribe el ID de la cita a reprogramar:\nEjemplo: CITA-123456\n\n- **9.** Cancelar (9)`,"AGENDA_REPROGRAMAR","PASO1_ID",{})];
  if (textoRaw==="4") return [R(`❌ Cancelar cita\n\nEscribe el ID de la cita a cancelar:\nEjemplo: CITA-123456\n\n- **9.** Cancelar (9)`,"AGENDA_CANCELAR","PASO1_ID",{})];
  if (textoRaw==="5") return [R(`✅ Marcar cita como completada\n\nEscribe el ID de la cita:\nEjemplo: CITA-123456\n\n- **9.** Cancelar (9)`,"AGENDA_COMPLETAR","PASO1_ID",{})];
  break;
}

// — Wizard crear cita (6 pasos) ------------------------------------------------
case "CITA_WIZARD": {
  if (textoRaw==="9") return [R(`Operación cancelada.\n\n${MENU_AGENDA_TXT}`,"MENU_AGENDA","",{})];
  if (paso==="PASO1_FECHA") {
    if (!esFechaValida(textoRaw)) return [R(`❌ Fecha inválida o en el pasado.\n\nFormato: YYYY-MM-DD\nEjemplo: 2025-12-20\n\n- **9.** Cancelar (9)`,"CITA_WIZARD","PASO1_FECHA",datos)];
    datos.fecha=textoRaw;
    return [R(`✅ Fecha: **${textoRaw}**\n\nPaso 2 de 6\n¿A qué hora será la cita?\n\nFormato 24 horas (HH:MM)\nEjemplo: 14:30\n\n- **9.** Cancelar (9)`,"CITA_WIZARD","PASO2_HORA",datos)];
  }
  if (paso==="PASO2_HORA") {
    if (!esHoraValida(textoRaw)) return [R(`❌ Hora inválida.\n\nFormato 24 horas (HH:MM)\nEjemplo: 14:30\n\n- **9.** Cancelar (9)`,"CITA_WIZARD","PASO2_HORA",datos)];
    datos.hora=textoRaw;
    return [R(`✅ Hora: **${textoRaw}**\n\nPaso 3 de 6\n¿A nombre de quién es la cita?\n\nEscribe el nombre completo.\n\n- **9.** Cancelar (9)`,"CITA_WIZARD","PASO3_NOMBRE",datos)];
  }
  if (paso==="PASO3_NOMBRE") {
    if (textoRaw.length<2) return [R(`❌ Escribe un nombre válido (mínimo 2 caracteres).\n\n- **9.** Cancelar (9)`,"CITA_WIZARD","PASO3_NOMBRE",datos)];
    datos.nombre=textoRaw;
    return [R(`✅ Nombre: **${textoRaw}**\n\nPaso 4 de 6\nCuéntame brevemente el motivo de la cita.\n\nEjemplo: Asesoría técnica\n\n- **9.** Cancelar (9)`,"CITA_WIZARD","PASO4_MOTIVO",datos)];
  }
  if (paso==="PASO4_MOTIVO") {
    if (textoRaw.length<2) return [R(`❌ Escribe un motivo válido.\n\n- **9.** Cancelar (9)`,"CITA_WIZARD","PASO4_MOTIVO",datos)];
    datos.motivo=textoRaw;
    return [R(`✅ Motivo: **${textoRaw}**\n\nPaso 5 de 6\n¿Cómo será la atención?\n\n- **1.** Presencial\n- **2.** Virtual\n- **3.** Llamada\n\n- **9.** Cancelar (9)`,"CITA_WIZARD","PASO5_CANAL",datos)];
  }
  if (paso==="PASO5_CANAL") {
    const canales={"1":"Presencial","2":"Virtual","3":"Llamada"};
    if (!canales[textoRaw]) return [R(`❌ Elige 1 (Presencial), 2 (Virtual) o 3 (Llamada).\n\n- **9.** Cancelar (9)`,"CITA_WIZARD","PASO5_CANAL",datos)];
    datos.canal=canales[textoRaw];
    const resumen=`Revisa la información de tu cita:\n\nFecha: **${datos.fecha}**\nHora: **${datos.hora}**\nCliente: **${datos.nombre}**\nMotivo: **${datos.motivo}**\nCanal: **${datos.canal}**\n\n¿Qué deseas hacer?\n- **1.** Confirmar y guardar\n- **2.** Editar información\n- **3.** Cancelar`;
    return [R(resumen,"CITA_WIZARD","PASO6_CONFIRMAR",datos)];
  }
  if (paso==="PASO6_CONFIRMAR") {
    if (textoRaw==="1") {
      const id="CITA-"+Date.now().toString().slice(-6);
      datos.id_generado=id;
      return [R(`🔍 Verificando disponibilidad para el **${datos.fecha}** a las **${datos.hora}**...`,"POST_CITA","",datos,"VERIFICAR_Y_GUARDAR_CITA")];
    }
    if (textoRaw==="2") return [R(`Empecemos de nuevo.\n\nPaso 1 de 6\n¿Cuál es la fecha de la cita?\n\nFormato: YYYY-MM-DD\n\n- **9.** Cancelar (9)`,"CITA_WIZARD","PASO1_FECHA",{})];
    if (textoRaw==="3") return [R(`Operación cancelada.\n\n${MENU_AGENDA_TXT}`,"MENU_AGENDA","",{})];
    return [R(`Elige 1 (Confirmar), 2 (Editar) o 3 (Cancelar).`,"CITA_WIZARD","PASO6_CONFIRMAR",datos)];
  }
  break;
}
case "POST_CITA": {
  if (textoRaw==="1") return [R(MENU_AGENDA_TXT,"MENU_AGENDA","",{})];
  if (textoRaw==="2") return [R(MENU_PRINCIPAL_TXT,"MENU_PRINCIPAL","",{})];
  return [R(`Elige 1 (Volver a Agenda) o 2 (Menú principal).`,"POST_CITA","",datos)];
}

// — Consultar agenda -----------------------------------------------------------
case "AGENDA_CONSULTAR": {
  if (textoRaw==="9") return [R(MENU_AGENDA_TXT,"MENU_AGENDA","",{})];
  if (paso==="PASO1_FECHA") {
    if (!esFechaValida(textoRaw) && textoRaw!=="HOY")
      return [R(`❌ Fecha inválida.\n\nFormato: YYYY-MM-DD\nO escribe HOY para ver las citas de hoy.\n\n- **9.** Cancelar (9)`,"AGENDA_CONSULTAR","PASO1_FECHA",datos)];
    const fechaBuscar = textoRaw==="HOY" ? new Date().toISOString().split("T")[0] : textoRaw;
    datos.fecha_consulta=fechaBuscar;
    return [R(`🔍 Buscando citas para el **${fechaBuscar}**...\n\n¿Deseas buscar otra fecha después?\n- **1.** Buscar otra fecha\n- **9.** Volver a Agenda (9)`,"AGENDA_CONSULTAR","PASO2_OPCIONES",datos,"VER_CITAS")];
  }
  if (paso==="PASO2_OPCIONES") {
    if (textoRaw==="1") return [R(`📅 Consultar agenda\n\nEscribe la fecha:\n\nFormato: YYYY-MM-DD\nO escribe HOY\n\n- **9.** Cancelar (9)`,"AGENDA_CONSULTAR","PASO1_FECHA",{})];
    return [R(MENU_AGENDA_TXT,"MENU_AGENDA","",{})];
  }
  break;
}

// — Reprogramar cita -----------------------------------------------------------
case "AGENDA_REPROGRAMAR": {
  if (textoRaw==="9") return [R(MENU_AGENDA_TXT,"MENU_AGENDA","",{})];
  if (paso==="PASO1_ID") {
    if (!textoRaw.startsWith("CITA-"))
      return [R(`❌ ID inválido.\n\nEjemplo: CITA-123456\n\n- **9.** Cancelar (9)`,"AGENDA_REPROGRAMAR","PASO1_ID",datos)];
    datos.id_cita=textoRaw;
    return [R(`🔄 Cita: **${textoRaw}**\n\nEscribe la nueva fecha:\n\nFormato: YYYY-MM-DD\nEjemplo: 2025-12-25\n\n- **9.** Cancelar (9)`,"AGENDA_REPROGRAMAR","PASO2_FECHA",datos)];
  }
  if (paso==="PASO2_FECHA") {
    if (!esFechaValida(textoRaw)) return [R(`❌ Fecha inválida o en el pasado.\n\nFormato: YYYY-MM-DD\n\n- **9.** Cancelar (9)`,"AGENDA_REPROGRAMAR","PASO2_FECHA",datos)];
    datos.nueva_fecha=textoRaw;
    return [R(`✅ Nueva fecha: **${textoRaw}**\n\nEscribe la nueva hora:\n\nFormato: HH:MM\nEjemplo: 10:00\n\n- **9.** Cancelar (9)`,"AGENDA_REPROGRAMAR","PASO3_HORA",datos)];
  }
  if (paso==="PASO3_HORA") {
    if (!esHoraValida(textoRaw)) return [R(`❌ Hora inválida.\n\nFormato: HH:MM\n\n- **9.** Cancelar (9)`,"AGENDA_REPROGRAMAR","PASO3_HORA",datos)];
    datos.nueva_hora=textoRaw;
    return [R(`¿Confirmas la reprogramación?\n\nCita: **${datos.id_cita}**\nNueva fecha: **${datos.nueva_fecha}**\nNueva hora: **${textoRaw}**\n\n- **1.** Confirmar\n- **2.** Cancelar`,"AGENDA_REPROGRAMAR","PASO4_CONFIRMAR",datos)];
  }
  if (paso==="PASO4_CONFIRMAR") {
    if (textoRaw==="1") return [R(`✅ Cita **${datos.id_cita}** reprogramada correctamente.\n\nNueva fecha: **${datos.nueva_fecha}** a las **${datos.nueva_hora}**\n\n- **1.** Volver a Agenda\n- **2.** Menú principal`,"POST_CITA","",datos,"ACTUALIZAR_CITA")];
    return [R(MENU_AGENDA_TXT,"MENU_AGENDA","",{})];
  }
  break;
}

// — Cancelar cita -------------------------------------------------------------
case "AGENDA_CANCELAR": {
  if (textoRaw==="9") return [R(MENU_AGENDA_TXT,"MENU_AGENDA","",{})];
  if (paso==="PASO1_ID") {
    if (!textoRaw.startsWith("CITA-"))
      return [R(`❌ ID inválido.\n\nEjemplo: CITA-123456\n\n- **9.** Cancelar (9)`,"AGENDA_CANCELAR","PASO1_ID",datos)];
    datos.id_cita=textoRaw;
    return [R(`⚠️ ¿Confirmas que deseas CANCELAR la cita **${textoRaw}**?\n\nEsta acción no se puede deshacer.\n\n- **1.** Sí, cancelar cita\n- **2.** No, volver a Agenda`,"AGENDA_CANCELAR","PASO2_CONFIRMAR",datos)];
  }
  if (paso==="PASO2_CONFIRMAR") {
    if (textoRaw==="1") return [R(`✅ Cita **${datos.id_cita}** cancelada correctamente.\n\n- **1.** Volver a Agenda\n- **2.** Menú principal`,"POST_CITA","",datos,"CANCELAR_CITA")];
    return [R(MENU_AGENDA_TXT,"MENU_AGENDA","",{})];
  }
  break;
}

// — Completar cita -------------------------------------------------------------
case "AGENDA_COMPLETAR": {
  if (textoRaw==="9") return [R(MENU_AGENDA_TXT,"MENU_AGENDA","",{})];
  if (paso==="PASO1_ID") {
    if (!textoRaw.startsWith("CITA-"))
      return [R(`❌ ID inválido.\n\nEjemplo: CITA-123456\n\n- **9.** Cancelar (9)`,"AGENDA_COMPLETAR","PASO1_ID",datos)];
    datos.id_cita=textoRaw;
    return [R(`✅ ¿Confirmas que deseas marcar como COMPLETADA la cita **${textoRaw}**?\n\n- **1.** Sí, marcar como completada\n- **2.** No, volver a Agenda`,"AGENDA_COMPLETAR","PASO2_CONFIRMAR",datos)];
  }
  if (paso==="PASO2_CONFIRMAR") {
    if (textoRaw==="1") return [R(`✅ Cita **${datos.id_cita}** marcada como completada.\n\n- **1.** Volver a Agenda\n- **2.** Menú principal`,"POST_CITA","",datos,"COMPLETAR_CITA")];
    return [R(MENU_AGENDA_TXT,"MENU_AGENDA","",{})];
  }
  break;
}

// ═══════════════════════════════════════════════════════════════════════════════
// OPCIÓN 2 — TAREAS COMPLETAS
// ═══════════════════════════════════════════════════════════════════════════════
case "MENU_TAREAS": {
  if (textoRaw==="9") return [R(MENU_PRINCIPAL_TXT,"MENU_PRINCIPAL","",{})];
  if (!/^[1-3]$/.test(textoRaw))
    return [R(OPCION_INVALIDA("1,2,3,9","Menú Tareas")+"\n\n"+MENU_TAREAS_TXT,"MENU_TAREAS","",{})];
  if (textoRaw==="1") return [R(`Vamos a crear tu tarea.\n\nPaso 1 de 3\n¿Cuál es el título de la tarea?\n\nEjemplo: Preparar informe mensual\n\n- **9.** Cancelar (9)`,"TAREA_WIZARD","PASO1_TITULO",{})];
  if (textoRaw==="2") return [R(`📋 Consultando tus tareas...`,"MENU_TAREAS","",{},"VER_TAREAS")];
  if (textoRaw==="3") return [R(`🔄 Cambiar estado de tarea\n\nEscribe el ID de la tarea:\nEjemplo: TAREA-123456\n\n- **9.** Cancelar (9)`,"TAREA_ESTADO","PASO1_ID",{})];
  break;
}

// — Wizard crear tarea (3 pasos) -----------------------------------------------
case "TAREA_WIZARD": {
  if (textoRaw==="9") return [R(MENU_TAREAS_TXT,"MENU_TAREAS","",{})];
  if (paso==="PASO1_TITULO") {
    if (textoRaw.length<2) return [R(`❌ Escribe un título válido.\n\n- **9.** Cancelar (9)`,"TAREA_WIZARD","PASO1_TITULO",datos)];
    datos.titulo=textoRaw;
    return [R(`✅ Título: **${textoRaw}**\n\nPaso 2 de 3\n¿Cuál es la prioridad?\n\n- **1.** Alta\n- **2.** Media\n- **3.** Baja\n\n- **9.** Cancelar (9)`,"TAREA_WIZARD","PASO2_PRIORIDAD",datos)];
  }
  if (paso==="PASO2_PRIORIDAD") {
