case "MENU_CONFIGURACION": {
  if (textoRaw==="9") return [R(MENU_PRINCIPAL_TXT,"MENU_PRINCIPAL","",{})];
  if (!/^[12]$/.test(textoRaw))
    return [R(OPCION_INVALIDA("1,2,9","Menú Configuración")+"\n\n"+MENU_CONFIGURACION_TXT,"MENU_CONFIGURACION","",{})];
  if (textoRaw==="1") return [R(`¿Cuál es tu nuevo nombre?\n\n- **9.** Cancelar (9)`,"CONFIG_WIZARD","PASO1_NOMBRE",{})];
  return [R(`¿A qué hora quieres recibir tus recordatorios?\n\nFormato 24 horas (HH:MM)\nEjemplo: 08:00\n\n- **9.** Cancelar (9)`,"CONFIG_WIZARD","PASO1_HORARIO",{})];
}

case "CONFIG_WIZARD": {
  if (textoRaw==="9") return [R(MENU_CONFIGURACION_TXT,"MENU_CONFIGURACION","",{})];
  if (paso==="PASO1_NOMBRE") {
    if (textoRaw.length<2) return [R(`❌ Escribe un nombre válido.\n\n- **9.** Cancelar (9)`,"CONFIG_WIZARD","PASO1_NOMBRE",datos)];
    datos.nuevo_nombre=textoRaw;
    return [R(`✅ Listo, tu nombre ahora es **${textoRaw}**.\n\n- **1.** Volver a Configuración\n- **2.** Ir al menú principal`,"POST_CONFIG","",datos,"ACTUALIZAR_CONFIG_NOMBRE")];
  }
  if (paso==="PASO1_HORARIO") {
    if (!esHoraValida(textoRaw)) return [R(`❌ Hora inválida.\n\nFormato: HH:MM\n\n- **9.** Cancelar (9)`,"CONFIG_WIZARD","PASO1_HORARIO",datos)];
    datos.nuevo_horario=textoRaw;
    return [R(`✅ Listo, tus recordatorios llegarán a las **${textoRaw}**.\n\n- **1.** Volver a Configuración\n- **2.** Ir al menú principal`,"POST_CONFIG","",datos,"ACTUALIZAR_CONFIG_HORARIO")];
  }
  break;
}
case "POST_CONFIG": {
  if (textoRaw==="1") return [R(MENU_CONFIGURACION_TXT,"MENU_CONFIGURACION","",{})];
  if (textoRaw==="2") return [R(MENU_PRINCIPAL_TXT,"MENU_PRINCIPAL","",{})];
  return [R(`Elige 1 o 2.`,"POST_CONFIG","",datos)];
}

// ── ADMIN ─────────────────────────────────────────────────────────────────────
case "MENU_ADMIN": {
  if (textoRaw==="9") return [R(MENU_PRINCIPAL_TXT,"MENU_PRINCIPAL","",{})];
  if (textoRaw==="1") return [R(`👥 Consultando usuarios...`,"MENU_ADMIN","",{},"VER_USUARIOS")];
  if (textoRaw==="2") return [R(`📋 **Logs recientes**\n\nFunción disponible desde Google Sheets.\n\n- **9.** Volver (9)`,"MENU_ADMIN","",{})];
  if (textoRaw==="3") return [R(`Vamos a registrar un nuevo usuario.\n\nPaso 1 de 3\n¿Cuál es el ID de Telegram del usuario?\n\nEjemplo: 123456789\n\n- **9.** Cancelar (9)`,"USUARIO_WIZARD","PASO1_TELEGRAM_ID",{})];
  if (textoRaw==="4") return [R(`🔐 Cambiar permiso de usuario\n\nEscribe el ID de Telegram del usuario:\n\n- **9.** Cancelar (9)`,"USUARIO_PERMISO","PASO1_TELEGRAM_ID",{})];
  return [R(OPCION_INVALIDA("1,2,3,4,9","Panel Admin")+"\n\n"+MENU_ADMIN_TXT,"MENU_ADMIN","",{})];
}

// — Wizard registrar usuario (3 pasos) ------------------------------------------
case "USUARIO_WIZARD": {
  if (textoRaw==="9") return [R(MENU_ADMIN_TXT,"MENU_ADMIN","",{})];
  if (paso==="PASO1_TELEGRAM_ID") {
    if (!/^\d+$/.test(textoRaw)) return [R(`❌ El ID de Telegram debe ser numérico.\n\n- **9.** Cancelar (9)`,"USUARIO_WIZARD","PASO1_TELEGRAM_ID",datos)];
    datos.telegram_user_nuevo=textoRaw;
    return [R(`✅ ID: **${textoRaw}**\n\nPaso 2 de 3\n¿Cuál es el nombre del usuario?\n\n- **9.** Cancelar (9)`,"USUARIO_WIZARD","PASO2_NOMBRE",datos)];
  }
  if (paso==="PASO2_NOMBRE") {
    if (textoRaw.length<2) return [R(`❌ Escribe un nombre válido.\n\n- **9.** Cancelar (9)`,"USUARIO_WIZARD","PASO2_NOMBRE",datos)];
    datos.nombre=textoRaw;
    return [R(`✅ Nombre: **${textoRaw}**\n\nPaso 3 de 3\n¿Qué rol tendrá?\n\n- **1.** Administrador\n- **2.** Usuario\n\n- **9.** Cancelar (9)`,"USUARIO_WIZARD","PASO3_ROL",datos)];
  }
  if (paso==="PASO3_ROL") {
    const roles={"1":"admin","2":"usuario"};
    if (!roles[textoRaw]) return [R(`❌ Elige 1 (Administrador) o 2 (Usuario).\n\n- **9.** Cancelar (9)`,"USUARIO_WIZARD","PASO3_ROL",datos)];
    datos.rol=roles[textoRaw];
    return [R(`¡Usuario registrado! ✅\n\nID: **${datos.telegram_user_nuevo}**\nNombre: **${datos.nombre}**\nRol: **${datos.rol}**\nPermitido: sí\n\n- **1.** Registrar otro usuario\n- **2.** Ir al menú principal`,"POST_USUARIO","",datos,"GUARDAR_USUARIO")];
  }
  break;
}
case "POST_USUARIO": {
  if (textoRaw==="1") return [R(MENU_ADMIN_TXT,"MENU_ADMIN","",{})];
  if (textoRaw==="2") return [R(MENU_PRINCIPAL_TXT,"MENU_PRINCIPAL","",{})];
  return [R(`Elige 1 o 2.`,"POST_USUARIO","",datos)];
}

// — Cambiar permiso de usuario ---------------------------------------------------
case "USUARIO_PERMISO": {
  if (textoRaw==="9") return [R(MENU_ADMIN_TXT,"MENU_ADMIN","",{})];
  if (paso==="PASO1_TELEGRAM_ID") {
    if (!/^\d+$/.test(textoRaw)) return [R(`❌ El ID de Telegram debe ser numérico.\n\n- **9.** Cancelar (9)`,"USUARIO_PERMISO","PASO1_TELEGRAM_ID",datos)];
    datos.telegram_user_target=textoRaw;
    return [R(`🔐 Usuario: **${textoRaw}**\n\n¿Qué deseas hacer?\n\n- **1.** Permitir acceso\n- **2.** Bloquear acceso\n\n- **9.** Cancelar (9)`,"USUARIO_PERMISO","PASO2_PERMISO",datos)];
  }
  if (paso==="PASO2_PERMISO") {
    if (textoRaw!=="1"&&textoRaw!=="2") return [R(`❌ Elige 1 (Permitir) o 2 (Bloquear).\n\n- **9.** Cancelar (9)`,"USUARIO_PERMISO","PASO2_PERMISO",datos)];
    datos.nuevo_permitido = textoRaw==="1";
    return [R(`✅ Usuario **${datos.telegram_user_target}** ahora está **${datos.nuevo_permitido ? "permitido" : "bloqueado"}**.\n\n- **1.** Volver a Admin\n- **2.** Menú principal`,"POST_USUARIO","",datos,"ACTUALIZAR_USUARIO")];
  }
  break;
}

} // end switch

return [R(`Reiniciando por seguridad.\n\n${MENU_PRINCIPAL_TXT}`,"MENU_PRINCIPAL","",{})];

const rows = $input.all().map(i => i.json).filter(r => Object.keys(r).length > 0);
